#!/bin/bash
set -e

# Ensure HOME is correctly set to the persistent data volume for all modes (gateway & dashboard).
# This ensures files generated by git, gh, ssh, and agy persist across container restarts,
# and prevents them from ending up in /root due to Docker/s6-overlay environment leakage.
export HOME=/opt/data/home
mkdir -p "$HOME"

MODE=${1:-gateway}

if [ "$MODE" = "dashboard" ]; then
  echo "Starting Huginn Dashboard..."

  TARGET_UID=${HERMES_UID:-1000}
  TARGET_GID=${HERMES_GID:-1000}

  # Remap hermes user and ensure /opt/data ownership if running as root so
  # dashboard and mnemosyne do not write root-owned files (e.g. install locks,
  # caches, db files) into the shared persistent volume.
  if [ "$(id -u)" = "0" ]; then
    groupmod -o -g "$TARGET_GID" hermes 2>/dev/null || true
    usermod -o -u "$TARGET_UID" -g "$TARGET_GID" hermes 2>/dev/null || true
    chown -R "$TARGET_UID:$TARGET_GID" /opt/data 2>/dev/null || true
  fi

  # Configure Nginx to rewrite the Host header to 127.0.0.1 and proxy to dashboard
  cat << 'EOF' > /tmp/nginx.conf
events {}
http {
    server {
        listen 9120;
        location / {
            proxy_pass http://127.0.0.1:9119;
            proxy_set_header Host 127.0.0.1;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
        }
    }
}
EOF
  nginx -c /tmp/nginx.conf

  if [ "$(id -u)" = "0" ]; then
    if [ -x /command/s6-setuidgid ]; then
      exec /command/s6-setuidgid hermes /bin/bash -c "/opt/hermes/.venv/bin/python -m mnemosyne.install && exec /usr/bin/tini -s -- /opt/hermes/.venv/bin/hermes dashboard --host 127.0.0.1 --insecure"
    else
      exec su -s /bin/bash hermes -c "/opt/hermes/.venv/bin/python -m mnemosyne.install && exec /usr/bin/tini -s -- /opt/hermes/.venv/bin/hermes dashboard --host 127.0.0.1 --insecure"
    fi
  else
    /opt/hermes/.venv/bin/python -m mnemosyne.install
    exec /usr/bin/tini -s -- /opt/hermes/.venv/bin/hermes dashboard --host 127.0.0.1 --insecure
  fi
else
  echo "Starting Huginn Gateway..."

  # 1. Setup SSH directory and keys natively in the persistent home directory
  mkdir -p "$HOME/.ssh" && chmod 700 "$HOME/.ssh"
  if [ -f /run/secrets/hermes_ssh_key ]; then
    echo "Configuring SSH key..."
    tr -d "\r" < /run/secrets/hermes_ssh_key > "$HOME/.ssh/id_rsa"
    echo "" >> "$HOME/.ssh/id_rsa"
    chmod 600 "$HOME/.ssh/id_rsa"
    ssh-keyscan github.com > "$HOME/.ssh/known_hosts" 2>/dev/null
    chmod 600 "$HOME/.ssh/known_hosts"

    # OpenSSH expands `~` in IdentityFile using the passwd home of the user it
    # runs as (/opt/data for the hermes user), NOT $HOME. The key ssh actually
    # reads is therefore the passwd-home copy, which nothing here maintains: it
    # drifts to a group/world-readable mode over time and ssh then refuses it
    # ("UNPROTECTED PRIVATE KEY FILE"), which breaks every git push over SSH.
    # Mirror both files onto the passwd home and pin the modes.
    PW_HOME="$(getent passwd "${HERMES_UID:-1000}" | cut -d: -f6)"
    if [ -n "$PW_HOME" ] && [ "$PW_HOME/.ssh" != "$HOME/.ssh" ]; then
      mkdir -p "$PW_HOME/.ssh"
      chmod 700 "$PW_HOME/.ssh"
      install -m 600 "$HOME/.ssh/id_rsa" "$PW_HOME/.ssh/id_rsa"
      if [ -f "$HOME/.ssh/known_hosts" ]; then
        install -m 600 "$HOME/.ssh/known_hosts" "$PW_HOME/.ssh/known_hosts"
      fi
    fi
  fi

  # 2. Configure GitHub CLI (gh) credentials
  if [ -n "${GH_SETUP_TOKEN}" ]; then
    echo "Logging in to GitHub CLI..."
    if echo "${GH_SETUP_TOKEN}" | gh auth login --with-token; then
      echo "GitHub CLI login successful."
    else
      echo "Warning: GitHub CLI authentication failed."
    fi
  fi

  # 3. Configure Git user name/email and safe directory
  git config --global user.name "${GIT_USER_NAME}"
  git config --global user.email "${GIT_USER_EMAIL}"
  git config --global safe.directory /app/vault

  # 4. Remove secret tokens from the process environment
  unset GH_SETUP_TOKEN
  unset GH_TOKEN
  unset GITHUB_TOKEN

  # 5. Initialize Mnemosyne and run the Hermes Agent gateway
  /opt/hermes/.venv/bin/python -m mnemosyne.install
  exec /opt/hermes/.venv/bin/hermes gateway run
fi
